import manifest from "./media-manifest.json";

/**
 * Resolves a `{ type, key }` media reference from the project/skill data into
 * the optimized asset generated by `npm run media` — path, intrinsic size and
 * blur placeholder. Keeping this indirection means the data files never hold
 * file paths, and the pipeline can change output naming without touching them.
 *
 * Returns null for an unfilled slot, which is the normal state until Harsh's
 * assets land: callers render the frame without the fill rather than break.
 */
export function getMedia(reference) {
  if (!reference) return null;
  const entry = manifest[reference.key];

  if (!entry) {
    if (import.meta.env.DEV) {
      console.warn(`[media] no manifest entry for "${reference.key}" — run \`npm run media\``);
    }
    return null;
  }

  const aspectRatio = entry.width / entry.height;

  return {
    ...entry,
    type: reference.type,
    aspectRatio,
    // Layouts branch on this rather than on the category, because a category
    // is not reliably one shape — product animation mixes 9:16 social cuts
    // with a 16:9 spot, and each needs different framing.
    orientation: aspectRatio < 1 ? "portrait" : "landscape",
  };
}

/** Every asset the site can show, used to warm the preloader. */
export const allMedia = manifest;
